import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { Heart, Bell, User, Menu, X, Home } from 'lucide-react';
import styles from './Navbar.module.css';

export default function Navbar() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const [menuOpen, setMenuOpen] = useState(false);
  const [dropdownOpen, setDropdownOpen] = useState(false);

  return (
    <header className={styles.header}>
      <div className={`container ${styles.inner}`}>
        {/* Logo */}
        <Link to="/" className={styles.brand}>
          <div className={styles.logoText}>ProBridge</div>
          <div className={styles.logoDivider} />
          <div className={styles.tagline}>We Connect World of Real Estate</div>
        </Link>

        {/* Desktop Nav */}
        <nav className={styles.nav}>
          <Link to="/search?listingType=Sell" className={styles.navLink}>Buy</Link>
          <Link to="/search?listingType=Rent" className={styles.navLink}>Rent</Link>
          <Link to="/search?buildingType=Commercial" className={styles.navLink}>Commercial</Link>
          <Link to="/post-property" className={styles.postBtn}>+ Post Property</Link>
        </nav>

        {/* Right Icons */}
        <div className={styles.actions}>
          {user ? (
            <>
              <Link to="/saved" className={styles.iconBtn} title="Saved">
                <Heart size={20} />
              </Link>
              <div className={styles.avatarWrap} onClick={() => setDropdownOpen(o => !o)}>
                {user.photo
                  ? <img src={user.photo} alt={user.name} className={styles.avatar} />
                  : <div className={styles.avatarInitials}>{user.name?.[0]?.toUpperCase()}</div>
                }
                {dropdownOpen && (
                  <div className={styles.dropdown}>
                    <Link to="/account" className={styles.dropItem} onClick={() => setDropdownOpen(false)}>My Account</Link>
                    <Link to="/account?tab=listings" className={styles.dropItem} onClick={() => setDropdownOpen(false)}>My Listings</Link>
                    <button className={styles.dropItem} onClick={() => { logout(); setDropdownOpen(false); navigate('/'); }}>
                      Sign Out
                    </button>
                  </div>
                )}
              </div>
            </>
          ) : (
            <>
              <Link to="/login"    className={styles.loginBtn}>Login</Link>
              <Link to="/register" className={styles.registerBtn}>Register</Link>
            </>
          )}

          {/* Hamburger */}
          <button className={styles.hamburger} onClick={() => setMenuOpen(o => !o)} aria-label="Menu">
            {menuOpen ? <X size={22} /> : <Menu size={22} />}
          </button>
        </div>
      </div>

      {/* Mobile Menu */}
      {menuOpen && (
        <div className={styles.mobileMenu}>
          <Link to="/search?listingType=Sell"           onClick={() => setMenuOpen(false)} className={styles.mobileLink}>Buy</Link>
          <Link to="/search?listingType=Rent"           onClick={() => setMenuOpen(false)} className={styles.mobileLink}>Rent</Link>
          <Link to="/search?buildingType=Commercial"    onClick={() => setMenuOpen(false)} className={styles.mobileLink}>Commercial</Link>
          <Link to="/post-property"                     onClick={() => setMenuOpen(false)} className={styles.mobileLink}>+ Post Property</Link>
          {user ? (
            <>
              <Link to="/saved"   onClick={() => setMenuOpen(false)} className={styles.mobileLink}>Saved Properties</Link>
              <Link to="/account" onClick={() => setMenuOpen(false)} className={styles.mobileLink}>My Account</Link>
              <button onClick={() => { logout(); setMenuOpen(false); navigate('/'); }} className={styles.mobileLink}>Sign Out</button>
            </>
          ) : (
            <>
              <Link to="/login"    onClick={() => setMenuOpen(false)} className={styles.mobileLink}>Login</Link>
              <Link to="/register" onClick={() => setMenuOpen(false)} className={styles.mobileLink}>Register</Link>
            </>
          )}
        </div>
      )}
    </header>
  );
}
